#root .ocloss ~ .octiles{ margin:-8px 0 32px; }
/* v34.xx (cw-endcards3), the critic on 59 (3 of 5, P1, twice): "the running slowly toast stays bright over the 80 percent scrim, the brightest thing on screen after the card". The page toast (#hubtoast, not the canvas feed) waits while the abandon question is up. Tiles 24px under the hero label (was 16). */
body:has(#pausebox.asking) #hubtoast{ visibility:hidden; }

check:
{v:'VER',what:'the page toast hides while the abandon question is up (the critic: a running slowly toast shines over the scrim)',
 run:function(){
   var pb, t, w, bad=null;
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     t=document.getElementById('hubtoast'); pb=document.getElementById('pausebox');
     if(!t||!pb) return 'SKIP: no toast or pause box';
     w=pb.classList.contains('asking'); pb.classList.add('asking');
     if(getComputedStyle(t).visibility!=='hidden') bad='the page toast still shows while the abandon question is up';
     if(!w) pb.classList.remove('asking');
     return bad;
   } finally {
     try{ var _p=document.getElementById('pausebox'); if(_p) _p.classList.remove('asking'); }catch(_e){}
     __topClear();
   } }},
